import{_ as t,o as s,c as e,a2 as p}from"./chunks/framework.BjkiRu3Q.js";const i="/assets/c98a8afcf633b7fe-20261015000317-yj3c5ks.hUCEO4Pa.png",r="/assets/3f98c8ec3009b17f-20261015000317-mhbters.bJOhRv3l.png",o="/assets/4feb27d83c315e54-20261015000317-2l6i1ke.Cxg_mRHX.png",_="/assets/130a3bd7eb839edf-20261015000317-l54rw1h.Cp9_CQHJ.png",c="/assets/2d637e187c1f57cc-20261015000317-0f5k8hw.BTX-dYPU.png",l="/assets/b7fe76397d236e4b-20261015000317-253cxrw.B5G7DP5v.png",n="/assets/614c262a9a0c51eb-20261015000317-sgqehkk.SS1N1ItE.png",H=JSON.parse('{"title":"HIMS密度分析优化并更新LP参数值","description":"","frontmatter":{"title":"HIMS密度分析优化并更新LP参数值","date":"2026-10-14T16:03:17.000Z","lastmod":"2026-10-14T16:03:17.000Z"},"headers":[],"relativePath":"guide/1049.md","filePath":"guide/EntisMAXIV/EntisMaxIV帮助文档/操作说明/罐监控操作/Hims分析优化/HIMS密度分析优化并更新LP参数值.md"}'),P={name:"guide/1049.md"};function m(d,a,h,L,S,I){return s(),e("div",null,[...a[0]||(a[0]=[p('<h1 id="hims密度分析优化并更新lp参数值" tabindex="-1">HIMS密度分析优化并更新LP参数值 <a class="header-anchor" href="#hims密度分析优化并更新lp参数值" aria-label="Permalink to &quot;HIMS密度分析优化并更新LP参数值&quot;">​</a></h1><h1 id="hims密度分析优化并更新lp参数值-1" tabindex="-1">HIMS密度分析优化并更新LP参数值 <a class="header-anchor" href="#hims密度分析优化并更新lp参数值-1" aria-label="Permalink to &quot;HIMS密度分析优化并更新LP参数值&quot;">​</a></h1><p>HIMS密度分析优化并更新LP参数值</p><p>为了更好的使用HIMS密度，满足HIMS密度需要不断优化调整的需要，EntisMax中加入了HIMS密度分析优化功能，通过不断跟踪记录罐的作业历史记录，分析趋势，并根据回归趋势算法，求出更加合理的LP参数值，通过更新仪表的LP参数值，让液位计的HIMS密度值更加精确与真实 下面，根据软件功能版本的不同，分别描述相关的使用说明</p><h3 id="标准版实现功能" tabindex="-1">标准版实现功能 <a class="header-anchor" href="#标准版实现功能" aria-label="Permalink to &quot;标准版实现功能&quot;">​</a></h3><p>标准版可以通过手动打开功能界面，打开此界面，需要管理员设置过权限并登陆，否则不能打开</p><p><img src="'+i+'" alt="LP更新提醒5"></p><p>在界面上选择记录的历史时间范围，软件会导入操作者指定的时间范围内的静态记录，并执行分析计算（<em>注意，软件为了稳定运行，限制最多导入最近的1万条记录，所以，时间范围选择过长，没有意义</em>）</p><p><img src="'+r+'" alt="LP更新提醒6"></p><p>使用此功能前提，要求在巡检命令中加入BZP7命令，并最好是BZP7和BB命令设置为连续执行，P7的值也将会记录在历史记录中，虽然，软件为了更好的兼容性，也允许导入无P7的数据记录，然后计算得出，但没有实时的数据记录来得好，所以推荐在巡检命令中加入BZP7命令</p><p>软件界面如下：</p><p><img src="'+o+'" alt="LP分析更新界面"></p><p>图一</p><ul><li>用户可以选择罐来切换针对不同罐进行操作，</li><li>如果一个罐下面有多个仪表，在更新LP参数值之前，需要确定选择哪个仪表更新操作</li></ul><p>软件会根据回归算法求得的LP参数值来计算预测的视密度值，然后会与当前HIMS密度值作对比，由用户来确定是否要通过更新LP值，来调整液位计的HIMS密度值，用户也可以通过参考相关系数，R2值来综合参考</p><h3 id="专业版功能" tabindex="-1">专业版功能 <a class="header-anchor" href="#专业版功能" aria-label="Permalink to &quot;专业版功能&quot;">​</a></h3><p>专业版在标准版的基础上增加了自动判断功能，软件会跟踪一个罐的作业情况，当罐完成一个作业循环后（从上一个进罐完成静止到下一个进罐完成静止为一个循环），会跟踪此循环的前后时间，自动读取此范围内历史记录，并执行相关分析算法，求出LP值，并预测HIMS密度值，当预测的HIMS密度值与当前HIMS密度值差值超过指定值时，就会提醒操作员是否更新LP参数值，如图：</p><p><img src="'+_+'" alt="LP更新提醒4"></p><p>如果，此时操作员没有登录帐户，则会显示如下界面：</p><p><img src="'+c+'" alt="LP更新提醒1"></p><p>如果，操作员未在现场，或长时间不操作，则此提示框会自动关闭，并在事件中心进行提示，如图：</p><p><img src="'+l+'" alt="LP更新提醒2"></p><p>操作员可以随时点击“处理”按钮，执行处理（请注意，此处理按钮会在软件重启后或一个比较长的时间后会失效）.</p><p>实际更新处理界面跟标准版一致，只不过会自动帮操作员选择好指定的罐，指定的时间范围，更新LP值操作都与标准版一致</p><p>♦由于此功能刚推出，所以暂时不开放自动更新LP参数值功能，等适当的时候，再开放</p><p>♦ 如果，用户不想使用此功能，也不想被提醒，则可以通过配置关闭此功能，关闭此功能后，界面上的操作菜单也会隐藏起来</p><p>关闭配置界面如图：</p><p><img src="'+n+'" alt="LP更新提醒7"></p>',28)])])}const M=t(P,[["render",m]]);export{H as __pageData,M as default};
